<template><section class="rounded-xl border p-4" aria-labelledby="evidence-title"><div class="flex items-center justify-between gap-3"><h3 id="evidence-title" class="font-bold">หลักฐานประกอบการลา</h3><label class="cursor-pointer rounded-lg border px-3 py-2 text-sm text-[#800000] focus-within:ring-2"><span>เพิ่มไฟล์</span><input class="sr-only" type="file" multiple accept=".pdf,.jpg,.jpeg,.png" @change="upload"></label></div><p class="mt-1 text-xs text-gray-500">PDF/JPG/PNG สูงสุดไฟล์ละ 10 MB</p><p v-if="busy" role="status" class="mt-3 text-sm text-gray-500">กำลังอัปโหลด...</p><ul v-else class="mt-3 space-y-2"><li v-for="item in items" :key="item.id" class="flex items-center justify-between gap-3 rounded-lg bg-gray-50 p-3"><div class="min-w-0"><p class="truncate font-medium">{{item.original_name}}</p><p class="text-xs" :class="color[item.verification_status]">{{status[item.verification_status]||item.verification_status}}<span v-if="item.verification_note"> · {{item.verification_note}}</span></p></div><button class="shrink-0 text-sm text-[#800000] underline" @click="download(item)">ดาวน์โหลด</button></li><li v-if="!items.length" class="rounded-lg bg-gray-50 p-3 text-sm text-gray-500">ยังไม่มีหลักฐาน</li></ul></section></template>
<script setup>import{ref,onMounted}from'vue';import api from '../axios';import{useAlertStore}from'../stores/alert';const props=defineProps({leaveId:{type:Number,required:true}}),alerts=useAlertStore(),items=ref([]),busy=ref(false),status={pending:'รอตรวจสอบ',verified:'ตรวจสอบแล้ว',rejected:'ไม่ผ่านการตรวจสอบ'},color={pending:'text-amber-700',verified:'text-green-700',rejected:'text-red-700'};const load=async()=>{try{items.value=(await api.get(`/leaves/${props.leaveId}/evidences`)).data}catch{alerts.error('โหลดหลักฐานไม่สำเร็จ')}};const upload=async ev=>{if(!ev.target.files.length)return;busy.value=true;try{const f=new FormData();[...ev.target.files].forEach(x=>f.append('files[]',x));f.append('evidence_type','supporting_document');await api.post(`/leaves/${props.leaveId}/evidences`,f);alerts.success('เพิ่มหลักฐานแล้ว');await load()}catch(e){alerts.error(e.response?.data?.message||'อัปโหลดไม่สำเร็จ')}finally{busy.value=false;ev.target.value=''}};const download=async e=>{try{const r=await api.get(`/leave-evidences/${e.id}/download`,{responseType:'blob'}),u=URL.createObjectURL(r.data),a=document.createElement('a');a.href=u;a.download=e.original_name;a.click();URL.revokeObjectURL(u)}catch{alerts.error('ดาวน์โหลดไม่สำเร็จ')}};onMounted(load);</script>
